# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
#
# Run a command, then append "<label> <wall seconds> <peak RSS MiB>" to a
# profile file. Peak RSS comes from getrusage(RUSAGE_CHILDREN), so it needs no
# extra tools (ru_maxrss is bytes on macOS, kilobytes on Linux).
#
# Usage: python3 measure.py <profile_file> <label> -- <command...>

import resource
import subprocess
import sys
import time


def main():
    profile, label = sys.argv[1], sys.argv[2]
    cmd = sys.argv[sys.argv.index("--") + 1:]
    t0 = time.monotonic()
    rc = subprocess.call(cmd)
    wall = time.monotonic() - t0
    rss = resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss
    mib = rss / (1 << 20) if sys.platform == "darwin" else rss / 1024
    with open(profile, "a") as f:
        f.write(f"{label} {wall:.3f} {mib:.1f}\n")
    sys.exit(rc)


if __name__ == "__main__":
    main()
